package com.omegaplus.proai;
import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.PendingIntent;import android.content.Intent;import android.os.Build;
import androidx.core.app.NotificationCompat;import androidx.core.app.NotificationManagerCompat;
import com.google.firebase.messaging.FirebaseMessagingService;import com.google.firebase.messaging.RemoteMessage;
public class OmegaMessagingService extends FirebaseMessagingService {
 private static final String CHANNEL_ID="omegaplus_updates";
 @Override public void onMessageReceived(RemoteMessage m){super.onMessageReceived(m);String title=m.getNotification()!=null&&m.getNotification().getTitle()!=null?m.getNotification().getTitle():m.getData().getOrDefault("title","Omegaplus Pro AI");String body=m.getNotification()!=null&&m.getNotification().getBody()!=null?m.getNotification().getBody():m.getData().getOrDefault("body","You have a new update.");createChannel();Intent launch=new Intent(this,MainActivity.class);launch.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?PendingIntent.FLAG_IMMUTABLE:0));NotificationCompat.Builder n=new NotificationCompat.Builder(this,CHANNEL_ID).setSmallIcon(getApplicationInfo().icon).setContentTitle(title).setContentText(body).setStyle(new NotificationCompat.BigTextStyle().bigText(body)).setContentIntent(pi).setAutoCancel(true).setPriority(NotificationCompat.PRIORITY_DEFAULT);try{NotificationManagerCompat.from(this).notify((int)(System.currentTimeMillis()&0x7fffffff),n.build());}catch(SecurityException ignored){}}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL_ID,"Omegaplus Pro AI notifications",NotificationManager.IMPORTANCE_DEFAULT);c.setDescription("Daily Best, Premium predictions, match start and result alerts");NotificationManager n=getSystemService(NotificationManager.class);if(n!=null)n.createNotificationChannel(c);}}
}